-- Strength, injury prevention, calf/Achilles rehab, detraining and cross-training (verified via Crossref/PubMed, Oct 2026)
insert into public.knowledge_sources (title, category, author, source_url, summary, takeaways) values
 ('Blagrove et al. (2018): strength and conditioning for distance runners – systematic review', 'strength', 'Sports Med 48:1117–1149',
  'https://doi.org/10.1007/s40279-017-0835-7', '24 studies: running economy improved 2–8 % vs control; 1.5–10 km time trials tended to improve; VO2max and body composition unaffected.',
  array['2–3 strength sessions/week, heavy + explosive/plyometric','Strength belongs in a running plan']),
 ('Balsalobre-Fernández et al. (2016): strength training and running economy in highly trained runners', 'strength', 'J Strength Cond Res 30:2361–2368',
  'https://doi.org/10.1519/JSC.0000000000001316', 'Meta-analysis (VO2max > 60): large effect on running economy (SMD −1.42) with 2–3×/week for 8–12 weeks.',
  array['Even well-trained runners gain economy from strength work']),
 ('Denadai et al. (2017): explosive, heavy and isometric strength training and running economy', 'strength', 'Sports Med 47:545–554',
  'https://doi.org/10.1007/s40279-016-0604-z', '16 studies: running economy −3.9 % overall (explosive −4.8 %, heavy −3.7 %, isometric −2.2 % n.s.); longer programmes gave more.',
  array['Mix heavy and explosive work']),
 ('Spiering et al. (2021): minimal dose to maintain physical performance', 'strength', 'J Strength Cond Res 35:1449–1458',
  'https://doi.org/10.1519/JSC.0000000000003964', 'Strength maintained for up to 32 weeks with 1 session/week (1 set per exercise) if the load stays high; endurance maintained with 2 sessions/week or 33–66 % less volume if intensity stays high.',
  array['1 heavy session/week maintains strength','While injured: keep intensity, cut volume']),
 ('Schumann et al. (2022): compatibility of concurrent aerobic and strength training', 'strength', 'Sports Med 52:601–612',
  'https://doi.org/10.1007/s40279-021-01587-7', '43 studies: no interference for maximal strength or hypertrophy; explosive strength slightly blunted, mainly when done in the same session (none with ≥ 3 h apart).',
  array['Strength and running can be combined; separate them by ≥ 3 h when possible']),
 ('Lauersen, Bertelsen & Andersen (2014): exercise interventions to prevent sports injuries', 'injury', 'Br J Sports Med 48:871–877',
  'https://doi.org/10.1136/bjsports-2013-092538', '25 RCTs, 26,610 people: strength training RR 0.315 for sports injuries; overuse injuries RR 0.527; stretching no effect.',
  array['Strength training cuts sports injuries by roughly two thirds in trials','Stretching alone does not prevent injuries']),
 ('Green et al. (2020): calf muscle strain injuries – return to play and recurrence', 'injury', 'Am J Sports Med 48:3306–3315',
  'https://doi.org/10.1177/0363546520959327', '149 calf strains: return to play 19 ± 11 days without aponeurosis damage vs 31 ± 13 days with severe damage; a running mechanism meant slower return; a previous calf strain raised recurrence risk 6.7×.',
  array['Expect ~3–5 weeks for a running calf strain','Previous calf strain = higher recurrence risk → rehab before returning']),
 ('Silbernagel et al. (2007): continued activity with a pain-monitoring model in Achilles tendinopathy', 'injury', 'Am J Sports Med 35:897–906',
  'https://doi.org/10.1177/0363546506298279', 'RCT: continuing to run and jump under a pain-monitoring model gave the same outcome as 6 weeks of rest.',
  array['Pain ≤ 5/10 during, settled by next morning, not worse week to week → carry on']),
 ('Beyer et al. (2015): heavy slow resistance vs eccentric training for Achilles tendinopathy', 'injury', 'Am J Sports Med 43:1704–1711',
  'https://doi.org/10.1177/0363546515584760', 'RCT: heavy slow resistance and eccentric training equally effective at 12 and 52 weeks; compliance 92 % (HSR) vs 78 %.',
  array['Heavy slow calf raises (3 s up, 3 s down) 3×/week']),
 ('O''Neill et al. (2019): isometric holds and Achilles tendinopathy pain', 'injury', 'Knee Surg Sports Traumatol Arthrosc 27:2765–2773',
  'https://doi.org/10.1007/s00167-018-5050-z', 'Heavy isometric holds gave no meaningful immediate pain relief in Achilles tendinopathy (counterpoint to patellar tendon studies).',
  array['Isometrics are a gentle start, not a painkiller']),
 ('Hébert-Losier et al. (2017): single-leg heel-raise test reference values', 'injury', 'Physiotherapy 103:446–452',
  'https://doi.org/10.1016/j.physio.2017.03.002', 'n = 566: median 24 (men) and 21 (women) single-leg heel raises on a 10° incline; limits of agreement about ±6 reps.',
  array['Return test: 20–25 single-leg calf raises pain-free']),
 ('Mujika & Padilla (2000): detraining – part II', 'cross', 'Sports Med 30:145–154',
  'https://doi.org/10.2165/00007256-200030030-00001', 'Losses are avoided by keeping intensity, reducing frequency only moderately and cutting volume a lot; cross-training helps.',
  array['Injured: same heart-rate zones on bike/rower, less volume']),
 ('Eyestone et al. (1993): deep-water running and cycling to maintain running performance', 'cross', 'Am J Sports Med 21:41–44',
  'https://doi.org/10.1177/036354659302100107', 'RCT: after 6 weeks of water running or cycling instead of running, 2-mile run time was unchanged.',
  array['Cross-training keeps running performance for weeks']),
 ('Wilber et al. (1996): deep-water running maintains aerobic performance in trained runners', 'cross', 'Med Sci Sports Exerc 28:1056–1062',
  'https://doi.org/10.1097/00005768-199608000-00017', '6 weeks of deep-water running (hard + easy, 5 days/week) maintained VO2max, ventilatory threshold and running economy.',
  array['Hard intervals in the water/on the bike keep VO2max']),
 ('Tanaka (1994): effects of cross-training', 'cross', 'Sports Med 18:330–339',
  'https://doi.org/10.2165/00007256-199418050-00005', 'Cross-training never beats training in the sport itself; specificity matters more for highly trained athletes.',
  array['Cross-training bridges an injury, it does not replace running long-term']);
